(() => {
  'use strict';

  let runtimeReady=false;
  let productCatalogRequested=false;
  let productCatalogStarted=false;
  let productCatalogReady=false;
  let dishFeaturesRequested=false;
  let dishFeaturesStarted=false;
  let catalogExtrasStarted=false;
  let productImagesIdle=false;
  let dishStylesReadyPromise=null;
  let dishWarmupScheduled=false;

  const ensureStylesheet=(selector,href,datasetKey)=>{
    let style=document.querySelector(selector);
    if(style?.sheet)return Promise.resolve();
    return new Promise((resolve,reject)=>{
      const onLoad=()=>resolve();
      const onError=()=>reject(new Error('Impossible de charger '+href));
      if(!style){
        style=document.createElement('link');
        style.rel='stylesheet';
        style.href=href;
        style.dataset[datasetKey]='style';
        style.addEventListener('load',onLoad,{once:true});
        style.addEventListener('error',onError,{once:true});
        document.head.appendChild(style);
        return;
      }
      style.addEventListener('load',onLoad,{once:true});
      style.addEventListener('error',onError,{once:true});
      if(style.sheet)resolve();
    });
  };
  const loadDishStyles=()=>{
    if(dishStylesReadyPromise)return dishStylesReadyPromise;
    dishStylesReadyPromise=Promise.all([
      ensureStylesheet('link[data-catalog-dishes]','./dishes.css?v=4','catalogDishes'),
      ensureStylesheet('link[data-catalog-liquid]','./catalog-liquid.css?v=5','catalogLiquid')
    ]).catch(error=>{
      dishStylesReadyPromise=null;
      throw error;
    });
    return dishStylesReadyPromise;
  };
  const loadRepurchaseSoon=()=>{
    if(document.querySelector('script[data-repurchase-soon]'))return;
    const script=document.createElement('script');
    script.src='./repurchase-soon.js?v=443';
    script.async=false;
    script.dataset.repurchaseSoon='script';
    document.body.appendChild(script);
  };
  const loadCatalogProductAdmin=()=>{
    if(document.querySelector('script[data-catalog-product-admin]'))return;
    const script=document.createElement('script');
    script.src='./catalog-product-admin.js?v=412';
    script.async=false;
    script.dataset.catalogProductAdmin='script';
    document.body.appendChild(script);
  };
  const warmDishImages=()=>window.COURSES_DISH_IMAGES?.warm?.();
  const loadDishAddedMarker=()=>{
    if(document.querySelector('script[data-dish-added-marker]'))return;
    const marker=document.createElement('script');
    marker.src='./dish-added-marker.js?v=408';
    marker.async=false;
    marker.dataset.dishAddedMarker='script';
    document.body.appendChild(marker);
  };
  const onDishLocalImagesReady=()=>{
    loadDishAddedMarker();
    warmDishImages();
  };
  const loadDishLocalImages=()=>{
    if(document.querySelector('script[data-dish-local-images]')){onDishLocalImagesReady();return}
    const images=document.createElement('script');
    images.src='./dish-local-images.js?v=482';
    images.async=false;
    images.dataset.dishLocalImages='script';
    images.addEventListener('load',onDishLocalImagesReady,{once:true});
    document.body.appendChild(images);
  };
  const loadLiquid=()=>{
    if(document.querySelector('script[data-catalog-liquid]')){loadDishLocalImages();return}
    const liquid=document.createElement('script');
    liquid.src='./catalog-liquid.js?v=441';
    liquid.async=false;
    liquid.dataset.catalogLiquid='script';
    liquid.addEventListener('load',loadDishLocalImages,{once:true});
    document.body.appendChild(liquid);
  };
  const loadDishes=()=>{
    if(document.querySelector('script[data-catalog-dishes]')){loadLiquid();return}
    loadDishStyles().then(()=>{
      if(document.querySelector('script[data-catalog-dishes]')){loadLiquid();return}
      const script=document.createElement('script');
      script.src='./dishes-ui.js?v=445';
      script.async=false;
      script.dataset.catalogDishes='script';
      script.addEventListener('load',loadLiquid,{once:true});
      document.body.appendChild(script);
    }).catch(error=>console.error('Chargement des styles Plats impossible',error));
  };
  const loadQuantities=()=>{
    if(window.COURSES_QUANTITIES){loadDishes();return}
    if(document.querySelector('script[data-catalog-quantities]'))return;
    const quantities=document.createElement('script');
    quantities.src='./catalog-quantities.js?v=478';
    quantities.async=false;
    quantities.dataset.catalogQuantities='script';
    quantities.addEventListener('load',loadDishes,{once:true});
    document.body.appendChild(quantities);
  };
  const startDishFeatures=()=>{
    dishFeaturesRequested=true;
    if(dishFeaturesStarted||!productCatalogReady)return;
    dishFeaturesStarted=true;
    loadQuantities();
  };
  const scheduleDishFeaturesWarmup=()=>{
    if(dishFeaturesStarted||dishWarmupScheduled)return;
    dishWarmupScheduled=true;
    const run=()=>{dishWarmupScheduled=false;startDishFeatures();};
    if(typeof window.requestIdleCallback==='function')window.requestIdleCallback(run,{timeout:900});
    else setTimeout(run,0);
  };
  const markProductCatalogReady=()=>{
    if(productCatalogReady)return;
    productCatalogReady=true;
    window.COURSES_CATALOG_PRODUCTS_READY=true;
    document.dispatchEvent(new CustomEvent('courses:catalog-products-ready'));
    window.COURSES_PRODUCT_IMAGES?.warm?.();
    if(dishFeaturesRequested)startDishFeatures();
  };
  const startProductCatalog=()=>{
    productCatalogRequested=true;
    if(productCatalogStarted||!runtimeReady)return;
    productCatalogStarted=true;
    markProductCatalogReady();
  };
  const startCatalogView=()=>{
    startProductCatalog();
    if(!catalogExtrasStarted){
      catalogExtrasStarted=true;
      loadRepurchaseSoon();
    }
    startDishFeatures();
  };
  document.addEventListener('courses:status-changed',event=>{
    const title=event.detail?.title;
    if(title==='Synchronisé'||title==='Mode test'){
      startProductCatalog();
      scheduleDishFeaturesWarmup();
    }
  });
  document.addEventListener('courses:product-images-idle',()=>{
    productImagesIdle=true;
    warmDishImages();
  });
  document.addEventListener('courses:view-changed',event=>{
    if(event.detail?.view!=='catalog')return;
    startCatalogView();
  });
  document.addEventListener('courses:settings-management-opened',loadCatalogProductAdmin);
  const loadRuntimeFeatures=()=>{
    if(document.querySelector('script[data-runtime-features]')){
      runtimeReady=true;
      if(productCatalogRequested)startProductCatalog();
      return;
    }
    const script=document.createElement('script');
    script.src='./runtime-features.js?v=480';
    script.async=false;
    script.dataset.runtimeFeatures='script';
    script.addEventListener('load',()=>{
      runtimeReady=true;
      if(productCatalogRequested)startProductCatalog();
    },{once:true});
    document.body.appendChild(script);
  };
  const loadAppUi=()=>{
    if(document.querySelector('script[data-app-ui]')){loadRuntimeFeatures();return}
    const script=document.createElement('script');
    script.src='./app-ui.js?v=442';
    script.async=false;
    script.dataset.appUi='script';
    script.addEventListener('load',loadRuntimeFeatures,{once:true});
    document.body.appendChild(script);
  };
  const bootstrap=()=>{
    loadAppUi();
    if(document.getElementById('catalogView')?.classList.contains('is-active'))startCatalogView();
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bootstrap,{once:true});
  else bootstrap();
})();